from ortools.sat.python import cp_model
import itertools
import json

def solve_guillotine_cutting():
    screen_length = 250
    screen_width = 250

    sprite_types = list(range(1, 11))
    length = {
        1: 167, 2: 114, 3: 167, 4: 83, 5: 70,
        6: 143, 7: 120, 8: 66, 9: 87, 10: 69
    }
    width = {
        1: 184, 2: 118, 3: 152, 4: 140, 5: 86,
        6: 166, 7: 160, 8: 148, 9: 141, 10: 165
    }
    design_points = {
        1: 30728, 2: 13452, 3: 25384, 4: 11620, 5: 6020,
        6: 23738, 7: 19200, 8: 9768, 9: 12267, 10: 11385
    }

    model = cp_model.CpModel()

    placed = {}
    x = {}
    y = {}
    rotated = {}
    effective_length = {}
    effective_width = {}

    for i in sprite_types:
        placed[i] = model.NewBoolVar(f"placed_{i}")
        rotated[i] = model.NewBoolVar(f"rotated_{i}")

        x[i] = model.NewIntVar(0, screen_length, f"x_{i}")
        y[i] = model.NewIntVar(0, screen_width, f"y_{i}")

        effective_length[i] = model.NewIntVar(0, max(length[i], width[i]), f"eff_len_{i}")
        effective_width[i] = model.NewIntVar(0, max(length[i], width[i]), f"eff_width_{i}")

        model.Add(effective_length[i] == length[i]).OnlyEnforceIf(rotated[i].Not())
        model.Add(effective_length[i] == width[i]).OnlyEnforceIf(rotated[i])

        model.Add(effective_width[i] == width[i]).OnlyEnforceIf(rotated[i].Not())
        model.Add(effective_width[i] == length[i]).OnlyEnforceIf(rotated[i])

        model.Add(x[i] + effective_length[i] <= screen_length).OnlyEnforceIf(placed[i])
        model.Add(y[i] + effective_width[i] <= screen_width).OnlyEnforceIf(placed[i])

    for i, j in itertools.permutations(sprite_types, 2):
        if i < j:
            left_of = model.NewBoolVar(f"left_of_{i}_{j}")
            right_of = model.NewBoolVar(f"right_of_{i}_{j}")
            below = model.NewBoolVar(f"below_{i}_{j}")
            above = model.NewBoolVar(f"above_{i}_{j}")

            model.AddBoolOr([left_of, right_of, below, above, placed[i].Not(), placed[j].Not()])

            model.Add(x[i] + effective_length[i] <= x[j]).OnlyEnforceIf(left_of)

            model.Add(x[j] + effective_length[j] <= x[i]).OnlyEnforceIf(right_of)

            model.Add(y[i] + effective_width[i] <= y[j]).OnlyEnforceIf(below)

            model.Add(y[j] + effective_width[j] <= y[i]).OnlyEnforceIf(above)

    objective_terms = []
    for i in sprite_types:
        objective_terms.append(design_points[i] * placed[i])

    model.Maximize(sum(objective_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 300.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        placements = []
        total_design_points = 0
        for i in sprite_types:
            if solver.Value(placed[i]) == 1:
                x_val = solver.Value(x[i])
                y_val = solver.Value(y[i])
                rot_val = solver.Value(rotated[i])
                total_design_points += design_points[i]
                placements.append([i - 1, x_val, y_val, rot_val])
        print(json.dumps({
            "placements": placements,
            "total_design_points": total_design_points
        }))
    else:
        print(json.dumps({
            "placements": [],
            "total_design_points": 0
        }))

if __name__ == "__main__":
    solve_guillotine_cutting()
